// Sur téléphone, le résultat de « Vérifier mon code » peut se trouver sous l’écran : on l’amène dans la zone visible.
function currRevealResult(){requestAnimationFrame(()=>{const r=$('#curr-result');if(!r)return;const behavior=matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',b=r.getBoundingClientRect(),panel=r.closest('.curr-practice');if(panel&&getComputedStyle(panel).position==='sticky'){const pr=panel.getBoundingClientRect();if(b.top<pr.top||b.bottom>pr.bottom)panel.scrollBy({top:b.top-pr.top-pr.height/3,behavior});return}const bottomBar=$('.bottom-nav')?.getBoundingClientRect().height||0;if(b.top<0||b.bottom>innerHeight-bottomBar-16)r.scrollIntoView({block:'center',behavior})})}
// La loupe ouvre la recherche avec le curseur déjà dans le champ (le champ peut apparaître après le chargement des données).
var currFocusSearch=false;
function currFocusSearchField(tries=0){requestAnimationFrame(()=>{const input=$('#curr-search');if(input){currFocusSearch=false;input.focus();input.setSelectionRange(input.value.length,input.value.length);return}if(tries<60&&aRoute.kind==='recherche')currFocusSearchField(tries+1);else currFocusSearch=false})}
// Recherche vide : quelques idées plutôt que quatre cartes « Entre un mot pour chercher ».
function currSearchSuggestions(){return `<section class="panel"><h2>Quelques idées pour commencer</h2><p>Tape un mot, ou essaie une de ces recherches :</p><ul class="curr-search-suggestions">${['boucle','variable','condition','print','FCFA'].map(w=>`<li><a href="#/recherche/${encodeURIComponent(w)}">${esc(w)}</a></li>`).join('')}</ul><p><a class="text-button" href="#/bibliotheque">Consulter aussi la bibliothèque de référence →</a></p></section>`}
// Typographie française dans les titres : espace insécable avant ? ! : ; » et après «, pour qu’un « ? » ne se retrouve pas seul sur une ligne.
function currFrenchSpacing(){if(state.lang==='en')return;for(const el of $$('main :is(h1,h2,h3,legend)')){const walker=document.createTreeWalker(el,NodeFilter.SHOW_TEXT);let node;while((node=walker.nextNode())){const text=node.nodeValue.replace(/ ([?!:;»])/g,'\u00a0$1').replace(/« /g,'«\u00a0');if(text!==node.nodeValue)node.nodeValue=text}}}

